use crate::fight_sync::{
    BASE_PLAYER_LOCAL_HANDLERS, BASE_PLAYER_LOCAL_MESSAGES, FIGHT_WINDOWS,
    REQUEST_REGISTRATION_NATIVES, TAPED_NATIVES,
};

/// One fight window from `data/fight-sync.toml` (generated by the docs repo's
/// `scripts/fight_sync_data.py`). Function names are exact names from the decoded pack.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct FightWindowData {
    pub number: u16,
    pub part: u16,
    pub page: &'static str,
    pub pack: &'static str,
    pub start_ids: &'static [&'static str],
    /// Callbacks only the start's direct-call chain registers, for a start the hook cannot see:
    /// the first pop of one arms and opens the window at once.
    pub arm_ids: &'static [&'static str],
    pub end_ids: &'static [&'static str],
    pub change_map_ids: &'static [&'static str],
    pub game_over_ids: &'static [&'static str],
    pub continue_ids: &'static [&'static str],
    pub player_local: &'static [&'static str],
    pub run_at_once: &'static [&'static str],
    pub window_functions: &'static [&'static str],
    /// Window functions whose call tree reads a taped native.
    pub taped_functions: &'static [&'static str],
    pub player_local_messages: &'static [i32],
    pub player_local_callback_ids: &'static [u32],
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum WindowCloseCause {
    End,
    ChangeMap,
    GameOver,
    Continue,
    PhaseLeft,
    Restart,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum WindowArming {
    StartId,
    ArmId,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum WindowState {
    Closed,
    /// A start id ran; the window opens on the next callback registration.
    Armed(&'static FightWindowData),
    Open(&'static FightWindowData),
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum WindowEvent {
    /// A start id ran; the window opens on the next callback registration.
    Armed(&'static FightWindowData, &'static str),
    Opened(&'static FightWindowData),
    /// An arm id popped: the window armed and opened at once.
    OpenedByArmId(&'static FightWindowData, &'static str),
    Closed(&'static FightWindowData, WindowCloseCause),
    /// An armed window that never opened was given up: nothing of it reached the guest.
    Disarmed(&'static FightWindowData, WindowCloseCause),
}

/// The fight window of the phase pack a game is in: closed, armed by a start id, or open from
/// the first callback registration after it (or from an arm id's pop) until an end, map change,
/// game over or continue id.
#[derive(Debug, Clone)]
pub struct FightWindow {
    pack: String,
    state: WindowState,
}

impl FightWindowData {
    pub fn close_cause(&self, name: &str) -> Option<WindowCloseCause> {
        if self.end_ids.contains(&name) {
            Some(WindowCloseCause::End)
        } else if self.change_map_ids.contains(&name) {
            Some(WindowCloseCause::ChangeMap)
        } else if self.game_over_ids.contains(&name) {
            Some(WindowCloseCause::GameOver)
        } else if self.continue_ids.contains(&name) {
            Some(WindowCloseCause::Continue)
        } else {
            None
        }
    }

    pub fn is_player_local_handler(&self, name: &str) -> bool {
        BASE_PLAYER_LOCAL_HANDLERS.contains(&name) || self.player_local.contains(&name)
    }

    pub fn is_player_local_message(&self, message: i32) -> bool {
        BASE_PLAYER_LOCAL_MESSAGES.contains(&message)
            || self.player_local_messages.contains(&message)
    }

    /// The guest replays a host entry only after the host's end mark for it when the entry may
    /// read a taped native: its call tree reads one, or the name is in none of this window's
    /// functions (unknown, so assumed to read one). Other entries start at once.
    pub fn entry_waits_for_host_end(&self, name: &str) -> bool {
        self.taped_functions.contains(&name) || !self.window_functions.contains(&name)
    }

    pub fn is_player_local_callback_id(&self, callback_id: u32) -> bool {
        self.player_local_callback_ids.contains(&callback_id)
    }
}

impl FightWindow {
    pub fn new(pack: &str) -> Self {
        Self {
            pack: pack.to_owned(),
            state: WindowState::Closed,
        }
    }

    pub const fn state(&self) -> WindowState {
        self.state
    }

    pub const fn open_window(&self) -> Option<&'static FightWindowData> {
        match self.state {
            WindowState::Open(row) => Some(row),
            WindowState::Closed | WindowState::Armed(_) => None,
        }
    }

    pub fn pack(&self) -> &str {
        &self.pack
    }

    pub fn enter_pack(&mut self, pack: &str) -> Option<WindowEvent> {
        if self.pack == pack {
            return None;
        }
        pack.clone_into(&mut self.pack);
        self.close(WindowCloseCause::PhaseLeft)
    }

    /// A script function of the current pack ran (popped, queued or traced). Close ids win over
    /// start and arm ids; either while the window is open is part of the fight and ignored. An
    /// arm id opens only a closed window or the one it belongs to.
    pub fn function_ran(&mut self, name: &str) -> Option<WindowEvent> {
        if let WindowState::Armed(row) | WindowState::Open(row) = self.state
            && let Some(cause) = row.close_cause(name)
        {
            return self.close(cause);
        }
        if matches!(self.state, WindowState::Open(_)) {
            return None;
        }
        if let Some((row, start_id)) = self.window_with(name, |row| row.start_ids) {
            if self.state == WindowState::Armed(row) {
                return None;
            }
            self.state = WindowState::Armed(row);
            return Some(WindowEvent::Armed(row, start_id));
        }
        let (row, arm_id) = self.window_with(name, |row| row.arm_ids)?;
        if matches!(self.state, WindowState::Armed(armed) if armed != row) {
            return None;
        }
        self.state = WindowState::Open(row);
        Some(WindowEvent::OpenedByArmId(row, arm_id))
    }

    pub fn restart(&mut self) -> Option<WindowEvent> {
        self.close(WindowCloseCause::Restart)
    }

    pub fn callback_registered(&mut self) -> Option<WindowEvent> {
        let WindowState::Armed(row) = self.state else {
            return None;
        };
        self.state = WindowState::Open(row);
        Some(WindowEvent::Opened(row))
    }

    fn window_with(
        &self,
        name: &str,
        ids: impl Fn(&'static FightWindowData) -> &'static [&'static str],
    ) -> Option<(&'static FightWindowData, &'static str)> {
        fight_windows_of_pack(&self.pack)
            .find_map(|row| ids(row).iter().find(|id| **id == name).map(|id| (row, *id)))
    }

    fn close(&mut self, cause: WindowCloseCause) -> Option<WindowEvent> {
        let event = match self.state {
            WindowState::Closed => None,
            WindowState::Armed(row) => Some(WindowEvent::Disarmed(row, cause)),
            WindowState::Open(row) => Some(WindowEvent::Closed(row, cause)),
        };
        self.state = WindowState::Closed;
        event
    }
}

pub fn fight_windows_of_pack(pack: &str) -> impl Iterator<Item = &'static FightWindowData> {
    FIGHT_WINDOWS.iter().filter(move |row| row.pack == pack)
}

/// The line logged once per pack entry: how many windows the pack has and what arms them.
pub fn pack_windows_line(pack: &str) -> String {
    let rows: Vec<&FightWindowData> = fight_windows_of_pack(pack).collect();
    let ids = |of: fn(&FightWindowData) -> &'static [&'static str]| {
        rows.iter()
            .flat_map(|row| of(row).iter().copied())
            .collect::<Vec<_>>()
            .join(", ")
    };
    format!(
        "fight window: pack {pack} has {} windows, start ids [{}], arm ids [{}]",
        rows.len(),
        ids(|row| row.start_ids),
        ids(|row| row.arm_ids)
    )
}

pub fn is_taped_native(name: &str) -> bool {
    TAPED_NATIVES.contains(&name)
}

pub fn is_request_registration_native(name: &str) -> bool {
    REQUEST_REGISTRATION_NATIVES.contains(&name)
}
